const { test } = require('node:test');
const assert = require('node:assert/strict');
const { readingTimeMinutes } = require('../src/textstats');

// n copies of a one-word token, so the word count is exactly n.
const words = (n) => Array.from({ length: n }, () => 'word').join(' ');

const CASES = [
  ["", null, 0],
  ["x", null, 1],
  ["x x", null, 1],
  ["", 50, 0],
  ["x", 1, 1],
  ["x x", 1, 2],
  ["x x x", 1, 3],
  ["x x x", 2, 2],
  ["x x x x", 2, 2],
  ["x x x x x", 2, 3],
  ["x x x x", 4, 1],
  ["x x x x x", 4, 2],
  ["x x x x x x x x", 4, 2],
  ["x x x x x x x x x", 4, 3],
  ["x", 0.5, 2],
  ["x x", 0.5, 4],
  ["x", 0.25, 4],
  ["x", 1000, 1],
  ["x x x x x x x x x x", 3, 4],
  ["x x x x x x x x x x", 5, 2],
  ["x x x x x x x x x x", 10, 1],
  ["x x x x x x x x x x", 11, 1],
  ["x x x x x x x x x x x", 10, 2],
  ["a-b c'd", 1, 2],
  ["a-b c'd", 2, 1],
  ["a b. c d! e f?", 2, 3],
  ["1 2 3 4 5 6", 6, 1],
  ["1 2 3 4 5 6 7", 6, 2],
  ["...", 1, 0],
  ["--", 10, 0],
  ["\n", 10, 0],
  ["日本語 テキスト", 1, 2],
  ["日本語 テキスト", 2, 1],
  ["é", 1, 1],
  ["é è", 1, 2],
];

